    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row: counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    marker = next(v for v in counts if v != bg and v != 2)
    pts = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == marker]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    for c in range(c0, c1 + 1):
        if grid[r0][c] != marker: out[r0][c] = 2
        if grid[r1][c] != marker: out[r1][c] = 2
    for r in range(r0, r1 + 1):
        if grid[r][c0] != marker: out[r][c0] = 2
        if grid[r][c1] != marker: out[r][c1] = 2
    for i, (r, c) in enumerate(pts):
        for rr, cc in pts[i+1:]:
            dr, dc = rr-r, cc-c
            if dr == 0 and dc != 0: step = (0, 1 if dc > 0 else -1); n = abs(dc)
            elif dc == 0 and dr != 0: step = (1 if dr > 0 else -1, 0); n = abs(dr)
            elif abs(dr) == abs(dc) and dr != 0: step = (1 if dr > 0 else -1, 1 if dc > 0 else -1); n = abs(dr)
            else: continue
            if n > 1:
                for k in range(1, n):
                    y, x = r + step[0]*k, c + step[1]*k
                    if grid[y][x] == bg: out[y][x] = 2
    return out
